// Copies the pre-captured static HTML snapshots in prerendered/ over the
// matching routes in dist/ after every build, so crawlers that don't execute
// JavaScript (link-preview bots, some SEO tools) still see real per-page
// content instead of the empty SPA shell. Runs automatically via the
// "postbuild" npm script.
//
// These snapshots are static — they were captured once from the running app
// and are NOT regenerated by this script. After a content change to Home,
// Services, Contact, Gallery, or any service/subcategory page, re-run the
// capture process and overwrite the matching file(s) in prerendered/.
//
// Vite content-hashes the JS/CSS bundle filenames on every build, so a
// snapshot captured against an older build points at asset files that no
// longer exist. This script rewrites each snapshot's <script>/<link> tags to
// match the bundle Vite just built, so they never go stale between captures.

import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const rootDir = dirname(dirname(fileURLToPath(import.meta.url)))
const srcDir = join(rootDir, 'prerendered')
const destDir = join(rootDir, 'dist')

if (!existsSync(srcDir)) {
  console.warn('[copy-prerendered] prerendered/ not found, skipping.')
  process.exit(0)
}

const freshIndexHtml = readFileSync(join(destDir, 'index.html'), 'utf8')
const scriptTag = freshIndexHtml.match(/<script type="module"[^>]*><\/script>/)?.[0]
const styleTag = freshIndexHtml.match(/<link rel="stylesheet"[^>]*>/)?.[0]

if (!scriptTag || !styleTag) {
  console.error('[copy-prerendered] Could not find the current script/stylesheet tags in dist/index.html; aborting to avoid shipping snapshots with stale asset references.')
  process.exit(1)
}

function patchAssetTags(html) {
  return html
    .replace(/<script type="module"[^>]*><\/script>/, scriptTag)
    .replace(/<link rel="stylesheet"[^>]*>/, styleTag)
}

function copyAndPatch(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const srcPath = join(dir, entry.name)
    if (entry.isDirectory()) {
      copyAndPatch(srcPath)
      continue
    }
    const relPath = srcPath.slice(srcDir.length + 1)
    const destPath = join(destDir, relPath)
    mkdirSync(dirname(destPath), { recursive: true })
    writeFileSync(destPath, patchAssetTags(readFileSync(srcPath, 'utf8')))
  }
}

copyAndPatch(srcDir)
console.log('[copy-prerendered] Copied and patched prerendered snapshots into dist/.')
